import React, { useCallback, useEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';

const MIN_WIDTH = 220;
const MIN_HEIGHT = 170;
const DRAG_THRESHOLD_PX = 4;
// Pri ťahaní okna mu nedovolíme vyletieť úplne mimo stage – minimálne
// MIN_VISIBLE_PX musí ostať viditeľných na každej strane, aby ho používateľ
// mal stále ako uchopiť. Predtým pri pretiahnutí hore „mimo“ zmizla hlavička
// a okno sa nedalo dostať späť bez „Usporiadať okná“.
const MIN_VISIBLE_PX = 60;

// Univerzálny "okenný" rámik pre dlaždicu videa.
// V grid režime sa správa ako bežná položka mriežky a zobrazí overlay tlačidlá.
// Vo voľnom režime je absolútne pozicovaný, ťahateľný kdekoľvek (nielen za hlavičku)
// a má resize handles v rohoch, takže používateľ si môže okná rozhádzať kdekoľvek po obrazovke.
function FloatingVideoWindow({
  isFloating = false,
  position,
  onPositionChange,
  isFocused = false,
  isPinned = false,
  onTileClick,
  onPin,
  onUnpin,
  onMaximize,
  onPopout,
  onMinimize,
  showPinButton = true,
  showMaximizeButton = true,
  showPopoutButton = true,
  showMinimizeButton = true,
  rootElementRef,
  forceInAppFullscreen = false,
  onExitInAppFullscreen,
  header,
  className = '',
  zIndex,
  onActivate,
  children
}) {
  const dragStateRef = useRef(null);
  const resizeStateRef = useRef(null);
  const movedRef = useRef(false);
  const rootRef = useRef(null);
  const [isWindowFullscreen, setIsWindowFullscreen] = useState(false);

  const setRootRef = useCallback(
    (node) => {
      rootRef.current = node;
      if (typeof rootElementRef === 'function') {
        rootElementRef(node);
      } else if (rootElementRef) {
        rootElementRef.current = node;
      }
    },
    [rootElementRef]
  );

  const clampPosition = useCallback((nextPos, parentEl) => {
    if (!parentEl || !nextPos) return nextPos;
    const parentWidth = parentEl.clientWidth || window.innerWidth || 1024;
    const parentHeight = parentEl.clientHeight || window.innerHeight || 720;
    const w = nextPos.width || MIN_WIDTH;
    const minX = -(w - MIN_VISIBLE_PX);
    const maxX = parentWidth - MIN_VISIBLE_PX;
    const minY = 0; // hlavičku nikdy nepretiahneme nad horný okraj stage-u
    const maxY = parentHeight - MIN_VISIBLE_PX;
    return {
      ...nextPos,
      x: Math.min(Math.max(minX, nextPos.x), maxX),
      y: Math.min(Math.max(minY, nextPos.y), maxY)
    };
  }, []);

  // Drag začneme kdekoľvek na okne (nielen na hlavičke). Buttony a resize
  // handles si pointerdown stop-propagujú, takže ich klik dragom neaktivuje.
  const handleDragPointerDown = useCallback(
    (e) => {
      if (!isFloating) return;
      if (e.target.closest('button')) return;
      if (e.target.closest('.fvw-resize')) return;
      if (e.button !== undefined && e.button !== 0) return;
      const target = rootRef.current || e.currentTarget;
      try {
        target.setPointerCapture(e.pointerId);
      } catch (err) {
        /* ignore */
      }
      movedRef.current = false;
      dragStateRef.current = {
        pointerId: e.pointerId,
        target,
        parentEl: target.parentElement,
        startX: e.clientX,
        startY: e.clientY,
        origX: position?.x ?? 0,
        origY: position?.y ?? 0
      };
      onActivate?.();
      e.preventDefault();
    },
    [isFloating, position, onActivate]
  );

  const handleDragPointerMove = useCallback(
    (e) => {
      const drag = dragStateRef.current;
      if (!drag || drag.pointerId !== e.pointerId) return;
      const dx = e.clientX - drag.startX;
      const dy = e.clientY - drag.startY;
      if (!movedRef.current && (Math.abs(dx) > DRAG_THRESHOLD_PX || Math.abs(dy) > DRAG_THRESHOLD_PX)) {
        movedRef.current = true;
      }
      const nextPos = {
        x: drag.origX + dx,
        y: drag.origY + dy,
        width: position.width,
        height: position.height
      };
      onPositionChange?.(clampPosition(nextPos, drag.parentEl));
    },
    [onPositionChange, position, clampPosition]
  );

  const handleDragPointerUp = useCallback((e) => {
    const drag = dragStateRef.current;
    if (!drag || drag.pointerId !== e.pointerId) return;
    try {
      drag.target.releasePointerCapture(e.pointerId);
    } catch (err) {
      /* ignore */
    }
    dragStateRef.current = null;
  }, []);

  const startResize = useCallback(
    (corner) => (e) => {
      if (!isFloating) return;
      const target = e.currentTarget;
      try {
        target.setPointerCapture(e.pointerId);
      } catch (err) {
        /* ignore */
      }
      resizeStateRef.current = {
        pointerId: e.pointerId,
        target,
        corner,
        startX: e.clientX,
        startY: e.clientY,
        origX: position.x,
        origY: position.y,
        origW: position.width,
        origH: position.height
      };
      onActivate?.();
      e.stopPropagation();
      e.preventDefault();
    },
    [isFloating, position, onActivate]
  );

  const handleResizePointerMove = useCallback(
    (e) => {
      const r = resizeStateRef.current;
      if (!r || r.pointerId !== e.pointerId) return;
      const dx = e.clientX - r.startX;
      const dy = e.clientY - r.startY;
      let nx = r.origX;
      let ny = r.origY;
      let nw = r.origW;
      let nh = r.origH;
      if (r.corner.includes('e')) nw = Math.max(MIN_WIDTH, r.origW + dx);
      if (r.corner.includes('s')) nh = Math.max(MIN_HEIGHT, r.origH + dy);
      if (r.corner.includes('w')) {
        const dw = Math.min(dx, r.origW - MIN_WIDTH);
        nx = r.origX + dw;
        nw = r.origW - dw;
      }
      if (r.corner.includes('n')) {
        const dh = Math.min(dy, r.origH - MIN_HEIGHT);
        ny = r.origY + dh;
        nh = r.origH - dh;
      }
      onPositionChange?.({ x: nx, y: ny, width: nw, height: nh });
    },
    [onPositionChange]
  );

  const handleResizePointerUp = useCallback((e) => {
    const r = resizeStateRef.current;
    if (!r || r.pointerId !== e.pointerId) return;
    try {
      r.target.releasePointerCapture(e.pointerId);
    } catch (err) {
      /* ignore */
    }
    resizeStateRef.current = null;
  }, []);

  const handleClick = (e) => {
    if (movedRef.current) {
      // Práve sme dotiahli okno – kliknutie ignorujeme, aby sa neaktivoval pin.
      movedRef.current = false;
      return;
    }
    if (e.target.closest('button')) return;
    onTileClick?.();
  };

  useEffect(() => {
    const syncFullscreenState = () => {
      const fsElement =
        document.fullscreenElement ||
        document.webkitFullscreenElement ||
        document.mozFullScreenElement ||
        document.msFullscreenElement;
      setIsWindowFullscreen(Boolean(rootRef.current && fsElement === rootRef.current));
    };

    document.addEventListener('fullscreenchange', syncFullscreenState);
    document.addEventListener('webkitfullscreenchange', syncFullscreenState);
    document.addEventListener('mozfullscreenchange', syncFullscreenState);
    document.addEventListener('MSFullscreenChange', syncFullscreenState);
    syncFullscreenState();

    return () => {
      document.removeEventListener('fullscreenchange', syncFullscreenState);
      document.removeEventListener('webkitfullscreenchange', syncFullscreenState);
      document.removeEventListener('mozfullscreenchange', syncFullscreenState);
      document.removeEventListener('MSFullscreenChange', syncFullscreenState);
    };
  }, []);

  const exitFullscreen = useCallback(() => {
    try {
      if (document.fullscreenElement || document.webkitFullscreenElement) {
        if (document.exitFullscreen) {
          document.exitFullscreen().catch(() => {});
        } else if (document.webkitExitFullscreen) {
          document.webkitExitFullscreen();
        } else if (document.mozCancelFullScreen) {
          document.mozCancelFullScreen();
        } else if (document.msExitFullscreen) {
          document.msExitFullscreen();
        }
      }
    } catch {
      /* ignore */
    }
    // In-app fullscreen treba vypnúť cez parenta – browser nevie o ňom.
    onExitInAppFullscreen?.();
  }, [onExitInAppFullscreen]);

  // Spojený fullscreen stav: `:fullscreen` selektor (natívny) ALEBO
  // `fvw-app-fullscreen` class (in-app fallback). Oba spustia rovnaký
  // CSS layout (100vw/100vh, contain, hidden controls).
  const isAnyFullscreen = isWindowFullscreen || forceInAppFullscreen;

  const style = isFloating
    ? {
        position: 'absolute',
        left: position.x,
        top: position.y,
        width: position.width,
        height: position.height,
        zIndex
      }
    : undefined;

  // Vo fullscreene zámerne ignorujeme `style` z position prop – inline štýl
  // (left/top/width/height) by prebil CSS, takže by sa okno nenatiahlo na celú
  // obrazovku a video by ostalo orezané. CSS pre `.fvw:fullscreen` /
  // `.fvw.fvw-app-fullscreen` má `!important` na všetkých rozmeroch.
  const renderedStyle = isAnyFullscreen ? undefined : style;

  return (
    <div
      ref={setRootRef}
      className={`fvw ${isFloating ? 'fvw-floating' : 'fvw-grid'} ${isFocused ? 'fvw-focused' : ''} ${
        forceInAppFullscreen ? 'fvw-app-fullscreen' : ''
      } ${className}`}
      style={renderedStyle}
      onClick={handleClick}
      onPointerDown={handleDragPointerDown}
      onPointerMove={handleDragPointerMove}
      onPointerUp={handleDragPointerUp}
      onPointerCancel={handleDragPointerUp}
    >
      <div className="fvw-header">
        {isFloating && (
          <span className="fvw-grip" aria-hidden="true">
            ⋮⋮
          </span>
        )}
        <span className="fvw-title">{header}</span>
        <span className="fvw-controls">
          {showMinimizeButton && onMinimize && (
            <button
              type="button"
              className="fvw-btn"
              onPointerDown={(e) => e.stopPropagation()}
              onClick={(e) => {
                e.stopPropagation();
                onMinimize();
              }}
              title="Minimalizovať okno (zostane v lište hore)"
              aria-label="Minimalizovať"
            >
              ➖
            </button>
          )}
          {showPinButton &&
            (isPinned ? (
              <button
                type="button"
                className="fvw-btn"
                onPointerDown={(e) => e.stopPropagation()}
                onClick={(e) => {
                  e.stopPropagation();
                  onUnpin?.();
                }}
                title="Zrušiť pripnutie"
                aria-label="Zrušiť pripnutie"
              >
                📍
              </button>
            ) : (
              <button
                type="button"
                className="fvw-btn"
                onPointerDown={(e) => e.stopPropagation()}
                onClick={(e) => {
                  e.stopPropagation();
                  onPin?.();
                }}
                title="Pripnúť (zväčšiť hore)"
                aria-label="Pripnúť"
              >
                📌
              </button>
            ))}
          {showMaximizeButton && onMaximize && (
            <button
              type="button"
              className="fvw-btn"
              onPointerDown={(e) => e.stopPropagation()}
              onClick={(e) => {
                e.stopPropagation();
                onMaximize(rootRef.current);
              }}
              title="Fullscreen"
              aria-label="Fullscreen"
            >
              ⛶
            </button>
          )}
          {showPopoutButton && onPopout && (
            <button
              type="button"
              className="fvw-btn"
              onPointerDown={(e) => e.stopPropagation()}
              onClick={(e) => {
                e.stopPropagation();
                onPopout();
              }}
              title="Otvoriť v samostatnom okne (presunúť na iný monitor)"
              aria-label="Otvoriť v samostatnom okne"
            >
              🪟
            </button>
          )}
        </span>
      </div>
      <div className="fvw-body">{children}</div>
      {/* In-app fullscreen (bez natívneho Fullscreen API) má `.fvw` stále vnútri
          `.meeting-content` s overflow + nižším stacking kontextom – tlačidlo v
          dlaždici je pod header/toolbar/dock. Exit button portujeme na body. */}
      {isAnyFullscreen &&
        forceInAppFullscreen &&
        typeof document !== 'undefined' &&
        createPortal(
          <button
            type="button"
            className="fvw-fullscreen-exit fvw-fullscreen-exit-portal"
            onPointerDown={(e) => e.stopPropagation()}
            onClick={(e) => {
              e.stopPropagation();
              exitFullscreen();
            }}
            title="Späť z fullscreen"
            aria-label="Späť z fullscreen"
          >
            ✕ Späť
          </button>,
          document.body
        )}
      {isAnyFullscreen && !forceInAppFullscreen && (
        <button
          type="button"
          className="fvw-fullscreen-exit"
          onPointerDown={(e) => e.stopPropagation()}
          onClick={(e) => {
            e.stopPropagation();
            exitFullscreen();
          }}
          title="Späť z fullscreen (Esc)"
          aria-label="Späť z fullscreen"
        >
          ✕ Späť
        </button>
      )}
      {isFloating && (
        <>
          <div
            className="fvw-resize fvw-resize-se"
            onPointerDown={startResize('se')}
            onPointerMove={handleResizePointerMove}
            onPointerUp={handleResizePointerUp}
            onPointerCancel={handleResizePointerUp}
          />
          <div
            className="fvw-resize fvw-resize-sw"
            onPointerDown={startResize('sw')}
            onPointerMove={handleResizePointerMove}
            onPointerUp={handleResizePointerUp}
            onPointerCancel={handleResizePointerUp}
          />
          <div
            className="fvw-resize fvw-resize-ne"
            onPointerDown={startResize('ne')}
            onPointerMove={handleResizePointerMove}
            onPointerUp={handleResizePointerUp}
            onPointerCancel={handleResizePointerUp}
          />
          <div
            className="fvw-resize fvw-resize-nw"
            onPointerDown={startResize('nw')}
            onPointerMove={handleResizePointerMove}
            onPointerUp={handleResizePointerUp}
            onPointerCancel={handleResizePointerUp}
          />
        </>
      )}
    </div>
  );
}

export default FloatingVideoWindow;
